// React/TS function IR → Cheng source transpiler (M1 core).
//
// Consumes csg facts (csg.function / csg.op / csg.data / csg.type_decl) and
// emits Cheng functions reproducing the TS semantics. JS `number` maps to
// int64 (the repo is fixed-point throughout for digest determinism; cold
// float→int conversion is miscompiled, findings 2026-06-12). Nullable unions
// over primitives map to JS-falsy zero values ("", 0, false) — semantics
// preserving wherever the source branches on truthiness. Array higher-order
// methods (filter/map/sort/includes) are INLINED into loops, so arrow closures
// capture surrounding locals by simply being in the same scope. Everything
// outside the supported subset is a hard transpile error with diagnostics.

import { createHash } from "node:crypto";

export type CsgFact = { [key: string]: unknown };

export type TranspileDiagnostic = {
  functionId: string;
  functionName: string;
  opId: string;
  reason: string;
};

export type TranspileFunctionResult = {
  ok: boolean;
  name: string;
  code: string;
  preludeUsed: Set<string>;
  structsUsed: Set<string>;
  diagnostics: TranspileDiagnostic[];
};

type OpFact = CsgFact & { id: string; opKind: string; block?: string; ordinal?: number };
type TypeDeclMember = { name: string; optional: boolean; type: string };

// Mechanism 15 (RTCPeerConnection alias-teardown fold, ChessPage.tsx releaseVoiceRuntime): config
// for one handle box-ref's registered teardown idiom. eventProps is the EXACT, ORDERED set of
// `<alias>.<prop> = null` statements the fold requires (a partial/reordered/extra match never
// folds — see tryFoldHandleTeardown); closeMethod is the zero-arg method called inside the trailing
// `try { <alias>.<closeMethod>() } catch {}`.
export type HandleTeardownBridge = { bridgeFn: string; eventProps: readonly string[]; closeMethod: string };

export class TranspilerFactIndex {
  readonly opsById = new Map<string, OpFact>();
  private opsByFnCache: Map<string, OpFact[]> | undefined;

  // Ops grouped by owning function id (lazily built once per index; transpile-time
  // pre-registration walks one function's ops without rescanning the whole table).
  opsOf(fid: string): OpFact[] {
    if (this.opsByFnCache === undefined) {
      this.opsByFnCache = new Map();
      for (const o of this.opsById.values()) {
        const f = String(o.function ?? "");
        if (f.length === 0) continue;
        let a = this.opsByFnCache.get(f);
        if (a === undefined) { a = []; this.opsByFnCache.set(f, a); }
        a.push(o);
      }
    }
    return this.opsByFnCache.get(fid) ?? [];
  }
  readonly opsByBlock = new Map<string, OpFact[]>();
  readonly functionById = new Map<string, CsgFact>();
  readonly functionByName = new Map<string, CsgFact>();
  // Module fns grouped by DECLARING file (the function-side twin of typeDeclsByFile):
  // a bare callee naming a fn declared in the CALLER'S own file must resolve to that
  // file's binding — TS module scoping makes the local decl shadow every foreign
  // same-name module fn, while the flat first-wins functionByName table answers with
  // whichever module's fact the extraction order registered first (10+ UniMaker files
  // each declare a private `base64ToBytes`; under project facts UpdateCenterPage's
  // local helper resolved to walletChains' twin, the twin failed outside its own
  // closure, and the call went to the linker unresolved).
  readonly functionByNameInFile = new Map<string, CsgFact>();
  readonly dataById = new Map<string, unknown>();
  readonly typeDeclByName = new Map<string, CsgFact>();
  // Type decls grouped by their DECLARING file (see the type_decl constructor branch for
  // the exact-identity rationale). Same-name decls across modules resolve file-exactly.
  readonly typeDeclsByFile = new Map<string, CsgFact[]>();
  // Per-file NAMED IMPORT table for TYPE identity: importing file -> (local name ->
  // resolved project-relative module path). A type text written INSIDE a file means that
  // file's import binding — the checker spells parameter annotations with the LOCAL text
  // (`targets: Player[]`), and the flat first-wins decl table answers with a FOREIGN
  // same-name decl whenever another module declared the name first (every game engine has
  // its own Player/GameState — repro WerewolfPage renderPlayerGrid: the local `Player[]`
  // formal resolved to doudizhu's Player while every call site passed the werewolf
  // engine's Q_Player_8316baa4, and the @borrows source-authority check rejected the
  // formal/actual TypeId pair). Rewriting through the binding's exact module identity
  // (import("<resolved>").<Name>) feeds the same qualified-spelling machinery the engine's
  // own type_decl members already use; non-colliding names resolve back to the plain name
  // (the rewrite's flat-decl-is-the-same-decl check), so behavior changes only where the
  // flat table was answering with the wrong module's decl.
  readonly typeImportsByFile = new Map<string, Map<string, string>>();
  // Lazily built module-specifier view of typeDeclsByFile: the checker spells import()
  // operands as `$root/<project path without extension>` while decl loc.file is a real
  // file path — both normalize to the same key (leading `$root/` and trailing `.ts/.tsx`
  // stripped).
  private typeDeclsBySpecCache: Map<string, CsgFact[]> | undefined;

  typeDeclByModuleSpec(spec: string): CsgFact[] | undefined {
    if (this.typeDeclsBySpecCache === undefined) {
      this.typeDeclsBySpecCache = new Map();
      for (const [file, decls] of this.typeDeclsByFile) {
        this.typeDeclsBySpecCache.set(normalizeModuleSpecKey(file), decls);
      }
    }
    return this.typeDeclsBySpecCache.get(normalizeModuleSpecKey(spec));
  }
  // Qualified alias decl (Q_<Name>_<hash>) -> the decl's plain source name. Presence and
  // per-struct audit tables key on the plain name; this restores the origin identity.
  readonly qualifiedTypeOrigin = new Map<string, string>();
  readonly constLiterals = new Map<string, string>();
  // Module-level as-const OBJECT constants: name -> (member -> JSON string literal).
  // Admitted only when EVERY member parses as (readonly ident: string-literal) - one bad
  // pair abandons the whole table (honest unresolved-identifier failure, never partial).
  readonly constObjectMembers = new Map<string, Map<string, string>>();
  readonly constLiteralTypes = new Map<string, string>();
  // catch-clause parameter names grouped by OWNING FUNCTION id (csg.binding
  // declarationKind="catch" — the owner field is the enclosing csg.function, verified against
  // the real extraction; there is no op-level or block-level owner, so pairing to one try op
  // uses the intersection rule documented at the try lowering site).
  readonly catchParamsByFunction = new Map<string, Set<string>>();
  // csg.jsx element facts by id (jsx op children reference these via jsx_ref.coreFact).
  readonly jsxById = new Map<string, CsgFact>();
  // csg.jsx element fact by its PAIRED jsx op id (the extractor stamps fact.op during the
  // function-body op walk). The jsx childOp consumption path resolves a child's op back to
  // its element fact by exact identity — no loc/text heuristics.
  readonly jsxFactByOpId = new Map<string, CsgFact>();
  // Expression op ids consumed as JSX children (children[].childOp) — GLOBAL across
  // blocks: a jsx tree's expression ops may land in different blocks than the block
  // walk that would otherwise re-emit them as statements (double consumption).
  readonly childOpReferenced = new Set<string>();
  // External icon-package named imports (lucide-react): JSX tags matching these are
  // ICON components — visual assets routed to the asset channel (M3), not transpiled.
  readonly iconNames = new Set<string>();
  // Const ARRAY symbols whose element type is a named/inline type text (e.g. a module
  // `const categoryTabs = [...] as const` typed HomeChannelDefinition[]): name -> the
  // ELEMENT type text (still in TS spelling; consumers map it through a TypeMapper).
  readonly constArrayElemTypes = new Map<string, string>();
  // Const 2-D ARRAY symbols (`const KBD: string[][] = [[...],...]`): name -> the ELEMENT
  // type text ("string" for string[][]). A materialized 2-level managed seq has NO
  // compilable representation in the cold backend ("cold opaque seq managed element kind
  // unsupported", measured over local / global / call-result / for-in forms alike), so the
  // exact model is the ROW-STRUCT array: `type ChtConstRow_<N> = (cells: <elem>[])` and the
  // const getter builds and returns `<Row>[]` (1-level). Use sites index rows and read
  // `.cells` — every emitted shape compiles (stage3-verified 2026-09-18).
  readonly const2dRowElemTypes = new Map<string, string>();
  // The synthesized row-struct NAMES (the same set type queries and the emit side consult —
  // a receiver typed with one of these reads `.cells.<op>` for length/element ops).
  readonly const2dRowStructNames = new Set<string>();
  // Module-level variable symbols (declarationKind const|let) keyed `file::name` — the
  // module-let state channel's registry source and the listener-table classification's
  // exact type-text source. Multiple declarations of one name in one file are impossible
  // in TS; the same bare name across FILES is the norm (persistTimer x3), so every lookup
  // is file-scoped by construction.
  readonly moduleVarSymbols = new Map<string, CsgFact[]>();

  // Row-struct lowering lookup: the const's 2-D element type text and its synthesized row
  // struct name, or undefined when the name is not a registered 2-D const array.
  const2dRowStructOf(name: string): { struct: string; elemText: string } | undefined {
    const elemText = this.const2dRowElemTypes.get(name);
    if (elemText === undefined) return undefined;
    return { struct: `ChtConstRow_${name.replace(/[^A-Za-z0-9_]/g, "_")}`, elemText };
  }

  // LAZY row-struct decl registration (see the sym-scan note): the decl enters
  // typeDeclByName only when a unit actually resolves a value of it — the transpileR2c
  // extraTypeDecls sweep forwards synthesized.* decls into every unit's struct emission,
  // so an eager registration would leak every file's row structs everywhere.
  ensure2dRowDecl(rowStruct: string, elemText: string): void {
    if (!this.typeDeclByName.has(rowStruct)) {
      this.typeDeclByName.set(rowStruct, { kind: "synthesized.const2d_row", name: rowStruct, members: [{ name: "cells", optional: false, type: `${elemText}[]` }] } as CsgFact);
    }
  }

  // Register FILE-LEVEL `const name = (args) => ...` arrow functions: their csg.symbol
  // (declarationKind=const, initializerKind=ArrowFunction/*) carries the name; the arrow
  // body is an anonymous csg.function whose loc is CONTAINED by the symbol's loc. Such
  // functions are real callables but were never registered under their name — every
  // call site failed as `unsupported callee`. Containment (not equality) is the identity:
  // the symbol spans the whole `const name = arrow` declaration.
  registerFileLevelArrowFunctions(facts: readonly CsgFact[]): void {
    const symbols: Array<{ name: string; file: string; start: number; end: number }> = [];
    for (const fact of facts) {
      if (fact.kind !== "csg.symbol") continue;
      const declKind = String((fact as { declarationKind?: string }).declarationKind ?? "");
      const initKind = String((fact as { initializerKind?: string }).initializerKind ?? "");
      if (declKind !== "const") continue;
      if (!/Function/i.test(initKind)) continue;
      const name = String(fact.name ?? "");
      const loc = (fact as { loc?: { file?: string; start?: number; end?: number } }).loc;
      if (!name || this.functionByName.has(name) || !loc?.file) continue;
      symbols.push({ name, file: loc.file, start: loc.start ?? 0, end: loc.end ?? 0 });
      void 0;
    }
    if (symbols.length === 0) return;
    for (const fact of facts) {
      if (fact.kind !== "csg.function" || fact.name !== "<anonymous>") continue;
      const loc = (fact as { loc?: { file?: string; start?: number; end?: number } }).loc;
      if (!loc?.file) continue;
      for (const sym of symbols) {
        if (sym.file !== loc.file) continue;
        if ((loc.start ?? 0) >= sym.start && (loc.end ?? 0) <= sym.end + 1) {
          if (!this.functionByName.has(sym.name)) {
            this.functionByName.set(sym.name, fact);
            const key = `${sym.file}::${sym.name}`;
            if (!this.functionByNameInFile.has(key)) this.functionByNameInFile.set(key, fact);
          }
          break;
        }
      }
    }
  }

  constructor(facts: readonly CsgFact[], functionAliases?: ReadonlyMap<string, string>, baseIndex?: TranspilerFactIndex) {
    if (baseIndex !== undefined) {
      this.opsById = baseIndex.opsById;
      this.opsByBlock = baseIndex.opsByBlock;
      this.functionById = baseIndex.functionById;
      this.functionByName = new Map(baseIndex.functionByName);
      this.functionByNameInFile = new Map(baseIndex.functionByNameInFile);
      this.dataById = baseIndex.dataById;
      this.typeDeclByName = baseIndex.typeDeclByName;
      this.typeDeclsByFile = baseIndex.typeDeclsByFile;
      this.typeImportsByFile = baseIndex.typeImportsByFile;
      this.qualifiedTypeOrigin = baseIndex.qualifiedTypeOrigin;
      this.constLiterals = baseIndex.constLiterals;
      this.constObjectMembers = baseIndex.constObjectMembers;
      this.constLiteralTypes = baseIndex.constLiteralTypes;
      this.moduleVarSymbols = baseIndex.moduleVarSymbols;
      this.catchParamsByFunction = baseIndex.catchParamsByFunction;
      this.jsxById = baseIndex.jsxById;
      this.jsxFactByOpId = baseIndex.jsxFactByOpId;
      this.iconNames = baseIndex.iconNames;
      this.applyFunctionAliases(functionAliases);
      return;
    }
    for (const fact of facts) {
      if (fact.kind === "csg.import") {
        // Named-import type-identity table (see typeImportsByFile): project-relative
        // specifiers only — the exact identity a local type name resolves through.
        {
          const impFile = String((fact.loc as { file?: string } | undefined)?.file ?? "");
          const mod = String(fact.module ?? "");
          if (impFile.length > 0 && mod.startsWith(".")) {
            const resolved = resolveModuleSpec(impFile, mod);
            if (resolved !== undefined) {
              // Spell the synthesized qualified text EXACTLY like the checker's own
              // import()-operand form (`$root/<project path>`): the Q_<Name>_<hash> alias
              // name hashes the SPEC TEXT, so any other spelling mints a second alias decl
              // for the same module identity and splits nominal types across the cone
              // (repro WerewolfPage: `app/games/werewolf/engine` hashed Q_Player_06a5be1f
              // while the engine's own member texts hashed Q_Player_8316baa4).
              const specText = `$root/${resolved}`;
              for (const nm of (fact.named as Array<{ name?: string }> | undefined) ?? []) {
                if (typeof nm.name === "string" && nm.name.length > 0) {
                  let bucket = this.typeImportsByFile.get(impFile);
                  if (bucket === undefined) { bucket = new Map(); this.typeImportsByFile.set(impFile, bucket); }
                  if (!bucket.has(nm.name)) bucket.set(nm.name, specText);
                }
              }
            }
          }
        }
        if (String(fact.module ?? "") === "lucide-react" && fact.classification === "external_package") {
          for (const nm of (fact.named as Array<{ name?: string }> | undefined) ?? []) {
            if (typeof nm.name === "string" && nm.name.length > 0) this.iconNames.add(nm.name);
          }
        }
        continue;
      }
      if (fact.kind === "csg.jsx") {
        this.jsxById.set(String(fact.id), fact);
        const pairedOp = fact.op;
        if (typeof pairedOp === "string" && pairedOp.length > 0) this.jsxFactByOpId.set(pairedOp, fact);
      } else if (fact.kind === "csg.op") {
        const op = fact as OpFact;
        this.opsById.set(op.id, op);
        const block = typeof op.block === "string" ? op.block : "";
        if (!this.opsByBlock.has(block)) this.opsByBlock.set(block, []);
        this.opsByBlock.get(block)!.push(op);
        if (op.opKind === "jsx") {
          for (const c of ((op.children as Array<{ childOp?: string }> | undefined) ?? [])) {
            if (typeof c.childOp === "string" && c.childOp.length > 0) this.childOpReferenced.add(c.childOp);
          }
        }
      } else if (fact.kind === "csg.function") {
        const id = String(fact.id);
        this.functionById.set(id, fact);
        const name = typeof fact.name === "string" ? fact.name : "";
        if (name && name !== "<anonymous>" && !this.functionByName.has(name)) {
          this.functionByName.set(name, fact);
          const fnFile = String((fact.loc as { file?: string } | undefined)?.file ?? "");
          const key = `${fnFile}::${name}`;
          if (fnFile.length > 0 && !this.functionByNameInFile.has(key)) this.functionByNameInFile.set(key, fact);
        }
      } else if (fact.kind === "csg.data") {
        this.dataById.set(String(fact.id), (fact as { value?: unknown }).value);
      } else if (fact.kind === "csg.binding") {
        const b = fact as { declarationKind?: unknown; owner?: unknown; name?: unknown };
        if (b.declarationKind === "catch" && typeof b.owner === "string" && typeof b.name === "string") {
          if (!this.catchParamsByFunction.has(b.owner)) this.catchParamsByFunction.set(b.owner, new Set());
          this.catchParamsByFunction.get(b.owner)!.add(b.name);
        }
      } else if (fact.kind === "csg.symbol") {
        // `as const` module constants carry their VALUE in the type text:
        // readonly ["a","b",...] tuples and literal types inline at use sites.
        const name = String(fact.name ?? "");
        const declKind = String((fact as { declarationKind?: string }).declarationKind ?? "");
        const typeText = String((fact as { type?: string }).type ?? "");
        // Module-level variable registry (module-let state channel + listener-table
        // classification): `const|let x: T` symbols keyed by their exact declaring file.
        if ((declKind === "let" || declKind === "const") && String((fact as { symbolKind?: string }).symbolKind ?? "") === "variable") {
          const file = String((fact.loc as { file?: string } | undefined)?.file ?? "");
          if (name.length > 0 && file.length > 0) {
            const key = `${file}::${name}`;
            const bucket = this.moduleVarSymbols.get(key);
            if (bucket === undefined) this.moduleVarSymbols.set(key, [fact]);
            else bucket.push(fact);
          }
        }
        if (name.length > 0 && declKind === "const" && !this.constLiterals.has(name) && !this.constArrayElemTypes.has(name)) {
          // Const arrays of NAMED/INLINE element types (object tables like categoryTabs):
          // register the element type text so `typeof X[N]`, for_of, and .map/.reduce over
          // the symbol resolve their element type through the TypeMapper at use time.
          const stripped = typeText.replace(/import\("[^"]*"\)\./g, "").trim();
          // 2-D const arrays register on their OWN table (row-struct model — see the field
          // note) BEFORE the 1-D branch: "string[][]" would otherwise land in
          // constArrayElemTypes with the degraded element text "string[]" (the regex's
          // greedy head), mis-typing every row read as str[].
          const arr2dMatch = /^([A-Za-z_$][\w$.]*)\[\]\[\]$/.exec(stripped);
          if (arr2dMatch) {
            const rowStruct = `ChtConstRow_${name.replace(/[^A-Za-z0-9_]/g, "_")}`;
            this.const2dRowElemTypes.set(name, arr2dMatch[1]!.trim());
            this.const2dRowStructNames.add(rowStruct);
            // The row-struct DECL registers LAZILY (ensure2dRowDecl — at getter
            // materialization / type-query resolution): an eager registration here would
            // put EVERY file's row structs into typeDeclByName with a synthesized.* kind,
            // and the transpileR2c extraTypeDecls sweep (synthesized.* → the inner
            // invocation's usedStructs) would then emit every unit all other files'
            // ChtConstRow_* structs (repro PublishTypeSelector carrying mahjong engine's
            // ChtConstRow_hands).
            continue;
          }
          const arrMatch = /^(.+)\[\]$/.exec(stripped);
          if (arrMatch && !/^(?:readonly )?["\d]/.test(arrMatch[1]!.trim())) {
            this.constArrayElemTypes.set(name, arrMatch[1]!.trim());
            continue;
          }
        }
        if (name.length > 0 && declKind === "const" && !this.constLiterals.has(name)) {
          if (process.env.CHT_DEBUG_SYM === "1" && (name === "STORAGE_KEYS" || name === "WalletEntry")) {
            console.error(`[symdump] ${name} typeText=${JSON.stringify(typeText.slice(0, 140))} chengConstExpr=${chengConstExprProbe(fact)}`);
          }
          const chengConstExpr = typeof (fact as { chengConstExpr?: unknown }).chengConstExpr === "string" ? String((fact as { chengConstExpr?: unknown }).chengConstExpr) : "";
          const chengType = typeof (fact as { chengType?: unknown }).chengType === "string" ? String((fact as { chengType?: unknown }).chengType) : "";
          // OBJECT constants must be classified by their TYPE TEXT shape BEFORE the scalar
          // constLiterals branch: an as-const object can also carry a chengConstExpr (the whole
          // object text), and landing in constLiterals would make every member read an
          // unsupported-receiver failure instead of a literal.
          // Tolerant head: the type text may carry trailing whitespace/decorations after the
          // closing brace; membership strictness is enforced per-pair below (any unparseable
          // pair abandons the whole table).
          const objMembersHead = /^\{ (.*)/.exec(typeText.trim().replace(/\n/g, " "));
          if (chengConstExpr.length > 0 && chengType.length > 0 && !objMembersHead) {
            this.constLiterals.set(name, chengConstExpr);
            this.constLiteralTypes.set(name, chengType);
            continue;
          }
          const objMembers = objMembersHead;
          if (objMembers) {
            const pairs: Array<[string, string]> = [];
            let pairsOk = true;
            for (const rawPair of objMembers[1]!.split("; ")) {
                const pair = rawPair.trim();
                if (pair === "}") continue;   // trailing closing-brace segment
                const pm = /^readonly ([A-Za-z_$][\w$]*): ("(?:[^"\\]|\\.)*")$/.exec(pair);
                if (pm === null) { pairsOk = false; break; }
                pairs.push([pm[1]!, pm[2]!]);
            }
            if (pairsOk && pairs.length > 0) {
                this.constObjectMembers.set(name, new Map(pairs));
                continue;
            }
          }
          const tuple = /^readonly \[(.*)\]$/.exec(typeText.trim());
          if (tuple) {
            const items = tuple[1]!.match(/"([^"]*)"/g);
            if (items && items.length > 0) {
              this.constLiterals.set(name, `[${items.join(", ")}]`);
              this.constLiteralTypes.set(name, "str[]");
            }
          } else if (/^"[^"]*"$/.test(typeText.trim())) {
            this.constLiterals.set(name, typeText.trim());
            this.constLiteralTypes.set(name, "str");
          } else if (/^-?\d+$/.test(typeText.trim())) {
            this.constLiterals.set(name, `int64(${typeText.trim()})`);
            this.constLiteralTypes.set(name, "int64");
          }
        }
      } else if (fact.kind === "csg.type_decl") {
        const name = String(fact.name ?? "");
        if (name && !this.typeDeclByName.has(name)) this.typeDeclByName.set(name, fact);
        // File-scoped registry: TS resolves an UNQUALIFIED typeSource in the using file's
        // own scope, and `import("...").Name` resolves IN the imported file — the flat
        // first-wins name table answers neither exactly when two modules declare the same
        // name (every game engine declares its own `Player`/`GamePhase`; 7 same-name
        // `Props` interfaces). Grouped by declaring file; consumers pick the file-exact
        // decl before any flat-table fallback.
        const declFile = String((fact.loc as { file?: string } | undefined)?.file ?? "");
        if (name.length > 0 && declFile.length > 0) {
          let bucket = this.typeDeclsByFile.get(declFile);
          if (bucket === undefined) { bucket = []; this.typeDeclsByFile.set(declFile, bucket); }
          bucket.push(fact);
          // SELF-declaration identity entry: a plain type text written in the DECLARING
          // file means THAT decl — TS module scope again. Registering the file's own spec
          // into the same table rewriteLocalTypeImports consults routes the plain text
          // through the import()-qualified machinery, whose flat-decl-same check keeps
          // non-colliding names plain and mints the Q_ alias exactly where the checker's
          // own member texts already did (repro WerewolfPage createWerewolfGame:
          // `const players: Player[]` resolved to doudizhu's flat Player while the
          // game-state member text carried the engine-qualified Q_Player — the literal
          // constructed the foreign twin and the field store died on the pair).
          let selfBucket = this.typeImportsByFile.get(declFile);
          if (selfBucket === undefined) { selfBucket = new Map(); this.typeImportsByFile.set(declFile, selfBucket); }
          if (!selfBucket.has(name)) selfBucket.set(name, `$root/${declFile.replace(/\.tsx?$/, "")}`);
        }
      }
    }
    this.applyFunctionAliases(functionAliases);
    for (const ops of this.opsByBlock.values()) {
      ops.sort((a, b) => (Number(a.ordinal) || 0) - (Number(b.ordinal) || 0));
    }
  }

  // Names registered through applyFunctionAliases (component-local useCallback/const-arrow
  // aliases) — as opposed to real module-level functions that also live in functionByName. An
  // alias target is a component-closure function: it may read the enclosing component's free
  // vars, so calls to it must pass the injected free-var actuals and its compilation must inject
  // the same free-var params (S2 alias-fv slice). Module functions get NEITHER treatment.
  readonly aliasNames = new Set<string>();
  private applyFunctionAliases(functionAliases?: ReadonlyMap<string, string>) {
    if (functionAliases === undefined) return;
    for (const [name, fid] of functionAliases) {
      if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name)) continue;
      const target = this.functionById.get(fid);
      if (target === undefined) continue;
      // The .mjs's localFunctionAliases are ownership-proven component-closure writes. When the
      // extractor's project-wide name map already resolves this name to the SAME function fact
      // (the usual case: a const-arrow fn recorded under its own const name), the alias MUST
      // still be registered in aliasNames — call sites need the injected free-var actuals
      // prefix to match transpileWithInjectedParams' param injection (an unregistered alias
      // compiles with fv params but is called with zero actuals: a cold arity break). A name
      // resolving to a DIFFERENT (module-level) function keeps module precedence — unchanged.
      const existing = this.functionByName.get(name);
      if (existing !== undefined && existing !== target) continue;
      this.functionByName.set(name, target);
      const aliasFile = String((target.loc as { file?: string } | undefined)?.file ?? "");
      if (aliasFile.length > 0) this.functionByNameInFile.set(`${aliasFile}::${name}`, target);
      this.aliasNames.add(name);
    }
  }
}

// ---------------------------------------------------------------------------
// Type mapping
// ---------------------------------------------------------------------------

export class TypeMapper {
  readonly usedStructs = new Set<string>();
  private readonly index: TranspilerFactIndex;
  // Union-flatten shape targets (tryFlattenStructUnion): object-literal shape signature
  // (sanitized field name + mapped cheng type, name-sorted, "__"-joined — exactly
  // synthStructName's signature) -> the flattened ChtUnion_* decl name. A literal whose
  // exact field set equals one union member constructs AS the flattened struct (cheng
  // structs are nominal: the shape-synthesized twin could never enter the union's arrays).
  // Both type queries (exprType) and the emitter (synthesizeObjectStruct) resolve through
  // this table, so the two can never disagree.
  readonly unionFlattenShapeTargets = new Map<string, string>();

  constructor(index: TranspilerFactIndex) {
    this.index = index;
  }

  // Resolve one union member operand to its struct field list: a named decl's own members,
  // a single-type alias's target (recursively, through union aliases too), or an inline
  // object type text. Anything else (primitive member, unmapped base) returns undefined —
  // the union keeps its loud fail.
  private flattenStructUnionPartMembers(part: string): TypeDeclMember[] | undefined {
    let p = stripImportPrefixes(part).trim();
    while (p.startsWith("(") && p.endsWith(")") && balancedParens(p)) p = p.slice(1, -1).trim();
    const decl = this.index.typeDeclByName.get(p);
    if (decl !== undefined) {
      const members = (decl.members as TypeDeclMember[] | undefined) ?? [];
      if (members.length > 0) return members;
      const aliasTarget = String(decl.aliasTarget ?? "");
      if (aliasTarget.length === 0) return undefined;
      if (!aliasTarget.includes("|")) return this.flattenStructUnionPartMembers(aliasTarget);
      const inner = splitTopLevelUnion(aliasTarget).map((m) => stripImportPrefixes(m).trim()).filter((m) => m.length > 0);
      if (inner.length === 0) return undefined;
      const merged: TypeDeclMember[] = [];
      for (const innerPart of inner) {
        const innerMembers = this.flattenStructUnionPartMembers(innerPart);
        if (innerMembers === undefined) return undefined;
        merged.push(...innerMembers);
      }
      return merged;
    }
    return parseInlineObjectTypeMembers(p);
  }

  // Flatten a union whose every member resolves to a struct with SCALAR mappable fields
  // into one synthesized struct (the merged field set; fields absent from some members are
  // optional). Returns undefined — with usedStructs rolled back to the entry state — when
  // any member is not struct-shaped, any field maps to a non-scalar, or a shared field name
  // collides with a DIFFERENT cheng type (a real narrowing problem, never guessed).
  private tryFlattenStructUnion(t: string, parts: readonly string[]): { type: string } | undefined {
    const before = new Set(this.usedStructs);
    const rollback = (): undefined => {
      for (const s of this.usedStructs) if (!before.has(s)) this.usedStructs.delete(s);
      return undefined;
    };
    const memberLists: TypeDeclMember[][] = [];
    for (const part of parts) {
      const members = this.flattenStructUnionPartMembers(part);
      if (members === undefined || members.length === 0) return rollback();
      memberLists.push(members);
    }
    const fields = new Map<string, { ts: string; cheng: string; count: number; optional: boolean }>();
    for (const members of memberLists) {
      for (const m of members) {
        const cheng = this.map(m.type).type;
        if (cheng !== "str" && cheng !== "int64" && cheng !== "bool") return rollback();
        const prior = fields.get(m.name);
        if (prior !== undefined) {
          if (prior.cheng !== cheng) return rollback();
          prior.count += 1;
          prior.optional = prior.optional || m.optional === true;
          continue;
        }
        fields.set(m.name, { ts: m.type, cheng, count: 1, optional: m.optional === true });
      }
    }
    if (fields.size === 0) return rollback();
    const name = `ChtUnion_${stableInlineTypeHash(stripImportPrefixes(t).replace(/\s+/g, " ").trim())}`;
    if (!this.index.typeDeclByName.has(name)) {
      const total = memberLists.length;
      this.index.typeDeclByName.set(name, {
        kind: "synthesized.union_object", name,
        // Member types stay in TS spelling — emitStructs re-maps at emission time.
        members: [...fields.entries()].map(([fieldName, f]) => ({ name: sanitizeFieldName(fieldName), optional: f.optional || f.count < total, type: f.ts })),
      } as CsgFact);
    }
    this.usedStructs.add(name);
    // Register each member's exact scalar-field signature as a shape target.
    for (const members of memberLists) {
      const sorted = [...members].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
      const sigParts: string[] = [];
      let sigOk = true;
      for (const m of sorted) {
        const cheng = this.map(m.type).type;
        if (cheng !== "str" && cheng !== "int64" && cheng !== "bool") { sigOk = false; break; }
        sigParts.push(`${sanitizeFieldName(m.name)}_${cheng}`);
      }
      if (sigOk && !this.unionFlattenShapeTargets.has(sigParts.join("__"))) this.unionFlattenShapeTargets.set(sigParts.join("__"), name);
    }
    return { type: name };
  }

  // Structural-identity dedup for inline object annotations: an inline text whose member
  // set exactly equals a source-declared decl's member set (same names, optionality, and
  // type texts — order-insensitive, whitespace-normalized) IS that type in TS's structural
  // system, so map() returns the named decl instead of synthesizing a ChtInlineObj_* twin.
  // Twin synthesis made `formatLunarParts(guide.currentLunar)` a nominal TypeId mismatch
  // (the field carried ChtInlineObj_053aff49 while the formal wanted LunarParts — cold
  // @borrows source-authority reject, repro AstrologyDailyGuideCard). Only non-synthesized
  // decls are candidates (the value-model inventions are never source-declared formals),
  // so the candidate set is fixed once the fact index is built and the memo is sound.
  private inlineTwinMemo = new Map<string, string>();
  // Pure lookup (memoized, never mints) — also the spread-identity guard's pre-query
  // (spreadStructLiteralType): an annotation with a twin IS a real named type; one
  // without is a nominal-twin mint that must not shadow the spread derivation.
  inlineObjectStructuralTwin(t: string, members: TypeDeclMember[]): string | undefined {
    const cached = this.inlineTwinMemo.get(t);
    if (cached !== undefined) return cached.length > 0 ? cached : undefined; // "" = memoized miss
    if (this.inlineTwinMemo.has(t)) return undefined;
    // Checker-degraded annotation types normalize before the member match — the exact TS
    // identities, never guesses: `any`/`unknown` stamps (the checker's own degraded answer
    // over r2c state reads) are assignable BOTH ways, so they wildcard-match any declared
    // member type; a string/number/boolean LITERAL type widens to its base type (a literal
    // is assignable to its base). Everything else must normalize-equal exactly. Without
    // this the twin lookup misses, map() mints a nominal ChtInlineObj_* twin whose `any`
    // members emitStructs cannot map (silently dropped fields), and every consumer of the
    // annotation gets a field-incomplete struct (repro ZiweiPage
    // `profile: {...WENMO_BASIC_PROFILE, useTrueSolarTime, lateZiBoundary}` against the
    // AstrologyRuleProfile twin).
    const normType = (txt: string): string => {
      // Import qualification FIRST: decl members carry checker-qualified texts
      // (`import("$root/...").SocialMessageType`) while spread/return mirror texts print
      // the bare name (`SocialMessageType`) — same named type, one project namespace.
      // Cross-module same-name collisions that would bare-match two DIFFERENT decls hit
      // the ambiguous bail below (no unification, the mint path keeps over), so bare-name
      // comparison never unifies the wrong module's decl.
      const s = stripImportPrefixes(String(txt)).replace(/\s+/g, " ").trim();
      if (s === "any" || s === "unknown") return "*";
      if (/^(['"]).*\1$/.test(s)) return "string";
      if (/^-?\d+(\.\d+)?$/.test(s)) return "number";
      if (s === "true" || s === "false") return "boolean";
      return s;
    };
    const normSig = (ms: TypeDeclMember[]): string =>
      ms.map((m) => `${m.name}=${m.optional === true ? 1 : 0}:${normType(String(m.type))}`).sort().join("|");
    // Optionality-blind signature: same names, same type texts — the `?` flag ignored.
    // TS makes `x?: T` and `x: T | undefined` mutually assignable with the IDENTICAL
    // compiled carrier and absent-read zero; the checker's spread-type printing drops
    // the flag exactly on `| undefined` members (repro MessagesPage cloneConversations
    // `{...m}` mirror printed `extra: {...} | undefined` required over the decl's
    // `extra?:` — the strict sig missed, map() minted a nominal ChtInlineObj_* twin,
    // and the twin-typed messages slot died against the source-struct array the spread
    // identity built, cold exact-layout mismatch). Same-text is required — a flag-only
    // divergence never changes the value model.
    const normSigBlind = (ms: TypeDeclMember[]): string =>
      ms.map((m) => `${m.name}:${normType(String(m.type))}`).sort().join("|");
    const wanted = normSig(members);
    const wantedBlind = normSigBlind(members);
    const wantedNames = new Set(members.map((m) => String(m.name)));
    const annByName = new Map(members.map((m) => [String(m.name), m]));
    let twin: string | undefined;
    let ambiguous = false;
    const admit = (declName: string): void => {
      if (twin !== undefined && twin !== declName) ambiguous = true;
      else if (twin === undefined) twin = declName;
    };
    for (const decl of this.index.typeDeclByName.values()) {
      if (ambiguous) break;
      if (String(decl.kind ?? "").startsWith("synthesized.")) continue;
      const declMembers = (decl.members as TypeDeclMember[] | undefined) ?? [];
      if (declMembers.length === 0 || String(decl.aliasTarget ?? "").length > 0) continue;
      if (declMembers.length !== members.length) continue;
      const declSig = normSig(declMembers);
      if (declSig === wanted) {
        admit(String(decl.name));
        continue;
      }
      if (normSigBlind(declMembers) === wantedBlind) {
        admit(String(decl.name));
        continue;
      }
      // Wildcard reconciliation: same name/optionality set; every divergence must be the
      // annotation side carrying any/unknown where the decl declares a concrete type (the
      // converse is NOT admitted — a concrete annotation never matches a degraded decl
      // member).
      let wildOk = true;
      const declByName = new Map(declMembers.map((m) => [String(m.name), m]));
      for (const [nm, am] of annByName) {
        const dm = declByName.get(nm);
        if (dm === undefined) { wildOk = false; break; }
        if (dm.optional === true !== (am.optional === true)) { wildOk = false; break; }
        const at = normType(String(am.type));
        const dt = normType(String(dm.type));
        if (at === dt) continue;
        if (at === "*" && dt !== "*") continue;
        wildOk = false; break;
      }
      if (wildOk) admit(String(decl.name));
    }
    if (ambiguous) twin = undefined;
    if (process.env.R2C_TWIN_DEBUG === "1" && twin === undefined) {
      process.stderr.write(`[twinmiss] text='${t.slice(0, 220)}'\n  wanted='${wanted.slice(0, 300)}'\n  blind='${wantedBlind.slice(0, 300)}'\n`);
      let shown = 0;
      for (const decl of this.index.typeDeclByName.values()) {
        if (String(decl.kind ?? "").startsWith("synthesized.")) continue;
        const dm = (decl.members as TypeDeclMember[] | undefined) ?? [];
        if (dm.length !== members.length) continue;
        if (shown >= 6) break;
        shown += 1;
        process.stderr.write(`  cand ${String(decl.name)}: sig='${normSig(dm).slice(0, 300)}' blind='${normSigBlind(dm).slice(0, 300)}'\n`);
      }
    }
    this.inlineTwinMemo.set(t, twin ?? "");
    return twin;
  }

  map(typeSource: string): { type?: string; reason?: string } {
    // `import("<file>").<Name>` exact module identity: the checker-qualified spelling
    // resolves <Name> IN <file> — the flat first-wins name table answers with a FOREIGN
    // same-name decl when another module declared the name first (every game engine has
    // its own `Player`/`GamePhase`). EVERY qualified spelling in the text (top-level,
    // array elements, union members, generic arguments) is rewritten to a COLLISION-SAFE
    // alias token (`Q_<Name>_<filehash>`) whose decl is synthesized once into
    // typeDeclByName (the same registration convention the synthesized map/union decls
    // use) — every downstream consumer (struct emission, struct field lookup, presence)
    // reads it through the same table, so the alias needs no special cases. A qualified
    // spelling whose flat-table entry IS the referenced decl rewrites to the plain name
    // (exact prior behavior); an unknown file/name pair keeps the text verbatim so the
    // strip + plain lookup + honest reason path runs unchanged.
    const typeSourceText = String(typeSource);
    if (typeSourceText.includes("import(")) {
      const rewritten = typeSourceText.replace(/import\s*\(\s*"([^"]*)"(?:\s*,\s*\{[\s\S]*\})?\s*\)\s*\.\s*([A-Za-z_$][\w$]*)/g, (full, spec: string, name: string) => {
        const decl = this.index.typeDeclByModuleSpec(spec)?.find((d) => String(d.name ?? "") === name);
        if (decl === undefined) return full;
        const flatDecl = this.index.typeDeclByName.get(name);
        if (String(flatDecl?.id ?? "") === String(decl.id)) return name;
        // Structurally identical flat twin: the qualified spelling's decl and the
        // flat-table decl are two same-named declarations with the EXACT same member
        // signature (neither an alias) — the collision the Q_ alias exists to prevent
        // cannot occur, because every field's name/optionality/type (hence the physical
        // layout) is identical. Rewriting to the plain name keeps ONE nominal type
        // across the cone; minting the alias instead mixed two nominal structs inside
        // one value flow (repro ProfilePage useAddressBook: profileTypes.AddressRecord
        // vs AddressManager.AddressRecord — the qualified spellings minted
        // Q_AddressRecord_* while the plain spellings resolved to the flat twin, and
        // ensureSingleDefault's return died at the cold borrow boundary against
        // persistAddresses' plain-typed formal).
        if (
          flatDecl !== undefined
          && String((flatDecl as { aliasTarget?: string }).aliasTarget ?? "").length === 0
          && String((decl as { aliasTarget?: string }).aliasTarget ?? "").length === 0
          && structMemberSignature((flatDecl.members as TypeDeclMember[] | undefined) ?? []) === structMemberSignature((decl.members as TypeDeclMember[] | undefined) ?? [])
        ) return name;
        const qName = `Q_${name}_${stableInlineTypeHash(spec)}`;
        if (!this.index.typeDeclByName.has(qName)) {
          this.index.typeDeclByName.set(qName, {
            kind: "synthesized.import_qualified", name: qName,
            members: (decl.members as TypeDeclMember[] | undefined) ?? [],
            aliasTarget: String((decl as { aliasTarget?: string }).aliasTarget ?? ""),
          } as CsgFact);
        }
        if (!this.index.qualifiedTypeOrigin.has(qName)) this.index.qualifiedTypeOrigin.set(qName, name);
        return qName;
      });
      if (rewritten !== typeSourceText) return this.map(rewritten);
    }
    let t = stripImportPrefixes(String(typeSource)).trim();
    while (t.startsWith("(") && t.endsWith(")") && balancedParens(t)) t = t.slice(1, -1).trim();
    if (t.length === 0) return { reason: "empty type" };
    if (t === "number") return { type: "int64" };
    if (t === "string") return { type: "str" };
    if (t === "boolean" || t === "bool" || t === "true" || t === "false") return { type: "bool" };
    if (t === "HTMLVideoElement") return { type: "int64" };
    // DOM element refs are opaque host handles (the shell owns the real element; the
    // transpiled code only carries the handle) — same contract as HTMLVideoElement.
    if (t === "HTMLDivElement" || t === "HTMLInputElement" || t === "HTMLCanvasElement" || t === "HTMLTextAreaElement" || t === "HTMLElement" || t === "HTMLSpanElement") return { type: "int64" };
    // Audio/media element handles: same opaque host-handle contract as the element list
    // above (HTMLAudioElement refs feed attachMediaStream-style element handoff; the
    // shell owns the real node). HTMLMediaElement is the shared parameter type of that
    // handoff — the handle identity is the same.
    if (t === "HTMLAudioElement" || t === "HTMLMediaElement") return { type: "int64" };
    // Web/Worker handle (`useRef<Worker | null>` postMessage/terminate holders): the
    // worker thread lives host-side; the transpiled code only carries the handle —
    // the exact MediaStream contract below. Method calls on the handle keep failing
    // loudly (no fabricated host channel).
    if (t === "Worker") return { type: "int64" };
    // RTCPeerConnection handle (`useRef<RTCPeerConnection | null>`): the WebRTC engine
    // lives host-side; the transpiled code only carries the handle — the exact
    // MediaStream/Worker opaque-handle contract above. Every engine member
    // (createOffer/setRemoteDescription/onicecandidate/...) keeps failing loudly as an
    // unsupported member on the int64 handle — the WebRTC wall itself is unchanged.
    if (t === "RTCPeerConnection") return { type: "int64" };
    // File handle (`useState<File | null>` pickers): the file object lives host-side;
    // the transpiled code carries the handle and reads host-derived scalars off it
    // (.name/.size keep failing loudly as property reads on the handle — no
    // fabricated file metadata). Same opaque-handle contract as MediaStream.
    if (t === "File") return { type: "int64" };
    // MediaStream (mechanism 13, cht-voice-dual-state-bridge §3.3): same "opaque host handle ->
    // int64 id" contract as HTMLVideoElement above — Cheng never models the browser/WebView
    // WebRTC engine's internal MediaStream structure, only carries the host-assigned handle.
    if (t === "MediaStream") return { type: "int64" };
    if (t === "void") return { type: "void" };
    // Cheng-side identity texts: the monomorph override machinery substitutes ALREADY-MAPPED
    // cheng type names into generic positions (returnTypeWithOverrides text-replace), so an
    // instance's narrowed return can arrive as literal cheng text (repro
    // buildControlVrfPayload__json_JsonNode: `return type: unsupported type 'json.JsonNode'`).
    // TS source never spells these (the "bool" identity above is the same precedent) — the
    // identity map is exact for synthesized texts and unreachable from source annotations.
    if (t === "str" || t === "int64" || t === "int32" || t === "float64" || t === "float32" || t === "uint64" || t === "json.JsonNode") return { type: t };
    if (/^['"].*['"]$/.test(t)) return { type: "str" };
    if (/^-?\d+$/.test(t)) return { type: "int64" };
    if (t.endsWith("[]")) {
      // `unknown[]` (expression-position): the JSON-boundary element fold — the same
      // audited judgment as the `value: unknown` PARAMETER fold (writeJson et al.: a TS
      // unknown in this corpus is bridge JSON whose exactly one honest carrier is a json
      // node). Scoped to unknown[] ONLY: `any[]` keeps its historical unmapped behavior
      // (widening it re-typed existing bool/str array-literal chains and broke their
      // established resolution order), and bare `unknown`/`any` stay unmapped too.
      if (t === "unknown[]") return { type: "json.JsonNode[]" };
      const elem = this.map(t.slice(0, -2));
      if (elem.type === undefined) return { reason: `array element: ${elem.reason}` };
      return { type: `${elem.type}[]` };
    }
    if (t.startsWith("[") && t.endsWith("]")) {
      const tupleItems = splitTopLevelObjectMembers(t.slice(1, -1));
      if (tupleItems.length === 0) return { reason: "empty tuple" };
      const mappedItems = tupleItems.map((item) => this.map(item));
      const bad = mappedItems.find((item) => item.type === undefined);
      if (bad) return { reason: `tuple element: ${bad.reason}` };
      const first = mappedItems[0]!.type!;
      if (!mappedItems.every((item) => item.type === first)) {
        // A 2-tuple `[string, V]` with an identifier-safe V IS the R2cEntry_str_<V> pair
        // struct — the same identity tuplePairEntryShape (constructed `[k, v]` literals)
        // and recordDictIdentityOf (Object.entries chains) synthesize, so a DECLARED
        // tuple annotation (callback params/returns — e.g. cloneState's nested
        // `([candidateId, candidate]) => [candidateId, {...candidate}]` whose fn
        // returnType text is the tuple) and the constructed values agree on one model.
        // The V admission is the tag round-trip (legal identifier, member re-map):
        // scalars, declared structs, and synthesized dict/pair names. json/array values
        // (dotted/Arr spellings) keep the loud fail, as do every other shape.
        if (mappedItems.length === 2 && first === "str") {
          const vt = mappedItems[1]!.type!;
          const roundTrips = vt === "str" || PRIMITIVE_CHENG_TYPES.has(vt) || vt.startsWith("R2cMap_") || vt.startsWith("R2cEntry_") || this.index.typeDeclByName.has(vt);
          if (roundTrips && vt !== "str") {
            const entryT = `R2cEntry_str_${vt}`;
            if (!this.index.typeDeclByName.has(entryT)) {
              this.index.typeDeclByName.set(entryT, {
                kind: "synthesized.map_entry", name: entryT,
                members: [
                  { name: "key", optional: false, type: "string" },
                  { name: "value", optional: false, type: tsSpellingOfChengType(vt) },
                ],
              } as CsgFact);
            }
            this.usedStructs.add(entryT);
            return { type: entryT };
          }
        }
        return { reason: `heterogeneous tuple '${t}' not supported` };
      }
      return { type: `${first}[]` };
    }
    const arrayMatch = /^(?:Array|ReadonlyArray)\s*<(.+)>$/.exec(t);
    if (arrayMatch) {
      const elem = this.map(arrayMatch[1]!);
      if (elem.type === undefined) return { reason: `array element: ${elem.reason}` };
      return { type: `${elem.type}[]` };
    }
    // `Promise<T>` unwrap (S2 async-signature slice): an async function's declared Promise return
    // is a transparent wrapper IFF the body contains no `await` — the transpiler has NO await
    // codegen (an `await` op reaching emitExpr fails loudly), so every still-async body keeps
    // failing honestly and only synchronous bodies (whose Promise is unobservable: callers either
    // void the result or `.catch(fn)` it, and mechanism 9's reducible catch already drops the
    // wrapper for statically-provable pure-constant continuations) compile through. A Promise
    // VALUE passed around as data (stored, returned to a caller that awaits it) has no
    // representable Cheng type either way — those paths keep their own honest failures; this
    // unwrap never fabricates a channel for them.
    // MutableRefObject<T> / RefObject<T>: the r2c ref model folds the wrapper — the
    // slot holds T itself (.current reads/writes fold to the slot var).
    const refObjMatch = /^(?:Mutable)?(?:Readonly)?RefObject\s*<(.+)>$/.exec(t);
    if (refObjMatch) return this.map(refObjMatch[1]!);
    const promiseMatch = /^Promise\s*<(.+)>$/.exec(t);
    if (promiseMatch) return this.map(promiseMatch[1]!);
    if (promiseMatch) return this.map(promiseMatch[1]!);
    const partialMatch = /^Partial\s*<(.+)>$/.exec(t);
    if (partialMatch) return this.map(partialMatch[1]!);
    // Timer handles: `ReturnType<typeof setTimeout>` is an opaque host timer id — the
    // r2c deferred-effect model stores it as an int64 handle (clearTimeout takes it back).
    if (/^ReturnType\s*<\s*typeof\s+setTimeout\s*>$/.test(t)) return { type: "int64" };
    // `Record<K, V>` with a NUMERIC key and a mappable value lowers to the R2cMap dict —
    // the same keyed-map identity `Map<K,V>` gets (audited corpus shape: `Record<number,
    // string>` seat-notice dicts). Keyed reads/writes/values keep their exact scalar
    // typing instead of degrading to the json fold below. String-keyed records and any
    // unmappable side keep the json.JsonNode fold unchanged.
    if (/^Record\s*<\s*number\s*,/.test(t)) {
      const recInterior = t.slice(t.indexOf("<") + 1, t.lastIndexOf(">"));
      const recKt = recInterior.slice(0, recInterior.indexOf(",")).trim();
      const recVt = recInterior.slice(recInterior.indexOf(",") + 1).trim();
      const recKtM = this.map(recKt);
      const recVtM = this.map(recVt);
      if (recKtM.type !== undefined && recVtM.type !== undefined) {
        const recName = `R2cMap_${recKtM.type}_${recVtM.type}`.replace(/\[\]/g, "Arr");
        if (!this.index.typeDeclByName.has(recName)) {
          this.index.typeDeclByName.set(recName, {
            kind: "synthesized.map_type", name: recName,
            members: [
              { name: "keys", optional: false, type: `${recKt}[]` },
              { name: "vals", optional: false, type: `${recVt}[]` },
            ],
          } as CsgFact);
        }
        this.usedStructs.add(recName);
        return { type: recName };
      }
    }
    if (/^Record\s*<[^,]+,/.test(t)) return { type: "json.JsonNode" };
    // `Map<K,V>` synthesizes a two-parallel-arrays struct (keys/vals) — the r2c value
    // model for a keyed map. Method ops (.get/.set/.has/.delete/.values/.size) lower to
    // generated helper fns over the struct (see emitCall's R2cMap branch).
    const mapMatch = /^Map\s*<\s*(.+),\s*(.+)>$/.exec(t);
    if (mapMatch) {
      const kt = this.map(mapMatch[1]!.trim());
      const vt = this.map(mapMatch[2]!.trim());
      if (kt.type === undefined) return { reason: `Map key: ${kt.reason}` };
      if (vt.type === undefined) return { reason: `Map value: ${vt.reason}` };
      const name = `R2cMap_${kt.type}_${vt.type}`.replace(/\[\]/g, "Arr");
      if (!this.index.typeDeclByName.has(name)) {
        this.index.typeDeclByName.set(name, {
          kind: "synthesized.map_type", name,
          // Members carry the ORIGINAL TS element type texts (TypeMapper will map them
          // when the struct is emitted — passing cheng text here would fail the mapper
          // and silently drop the field).
          members: [
            { name: "keys", optional: false, type: `${mapMatch[1]!.trim()}[]` },
            { name: "vals", optional: false, type: `${mapMatch[2]!.trim()}[]` },
          ],
        } as CsgFact);
      }
      this.usedStructs.add(name);
      return { type: name };
    }
    // `Set<T>` lowers to `T[]`: the r2c value model represents a set as an array with
    // set semantics enforced at the mutation sites (add-after-includes check). Dedup is
    // observable-identical for every Set read (has/size/iteration), so the array
    // representation is exact for the transpiled subset.
    const setMatch = /^Set\s*<(.+)>$/.exec(t);
    if (setMatch) {
      const elem = this.map(setMatch[1]!);
      if (elem.type === undefined) return elem;
      return { type: `${elem.type}[]` };
    }
    // `keyof T` over a KNOWN object type decl (interface/type alias with members): the
    // key union of a string-keyed object is carried as str in the value model — every
    // key is a string and call sites pass the exact literal keys. An operand that is NOT
    // a known decl (single-file/dual-file extractions routinely omit the imported host
    // interface — `keyof Translations` with Translations living in another module) still
    // denotes an object type in TS: the value model carries its keys as str (the same
    // carrier the known case uses — the transpiled subset only consumes keyof-object
    // results as text keys). Non-object KNOWN operands keep failing loudly.
    const keyofMatch = /^keyof\s+(?:typeof\s+)?([A-Za-z_$][\w$]*)$/.exec(t);
    if (keyofMatch) {
      const keyofDecl = this.index.typeDeclByName.get(keyofMatch[1]!);
      const keyofMembers = (keyofDecl?.members as TypeDeclMember[] | undefined) ?? [];
      if (keyofDecl === undefined || keyofMembers.length > 0) return { type: "str" };
      return { reason: `keyof '${keyofMatch[1]}' operand is not a known object type` };
    }
    const inlineObjectMembers = parseInlineObjectTypeMembers(t);
    if (inlineObjectMembers !== undefined) {
      // Structural twin first (see inlineObjectStructuralTwin): a source-declared decl
      // with the exact member set IS this type — no nominal twin struct.
      const twin = this.inlineObjectStructuralTwin(t, inlineObjectMembers);
      if (twin !== undefined) {
        this.usedStructs.add(twin);
        return { type: twin };
      }
      const name = inlineObjectTypeName(t);
      if (!this.index.typeDeclByName.has(name)) {
        // r2c presence discriminator (R2C_SYNTH_PRESENCE_FIELD): these decls materialize
        // `useState<T | null>` slots whose JS null-ness rides no user field, so the internal
        // bool is appended unless the source annotation itself declares that name. Stored in
        // TS spelling ("boolean") like every member here — emitStructs re-maps at emission.
        const membersWithPresence = inlineObjectMembers.some((m) => m.name === R2C_SYNTH_PRESENCE_FIELD)
          ? inlineObjectMembers
          : [...inlineObjectMembers, { name: R2C_SYNTH_PRESENCE_FIELD, optional: false, type: "boolean" }];
        this.index.typeDeclByName.set(name, { kind: "synthesized.inline_object_type", name, members: membersWithPresence } as CsgFact);
      }
      this.usedStructs.add(name);
      return { type: name };
    }
    // `NonNullable<T>`: the null/undefined-stripping wrapper. Map the interior and let the
    // union branch's null filter do the exact stripping — `NonNullable<ReturnType<typeof
    // findMediaTransferEntry>>` over the declared `P2PMediaTransferEntry | null` return
    // resolves to P2PMediaTransferEntry, the same identity the `useRef<P2PMediaTransferEntry
    // | null>` slot path already maps. The greedy interior match carries nested generics
    // (`NonNullable<A<B>>` -> `A<B>`); an unmappable interior keeps its own reason (no
    // fabrication).
    const nonNullableMatch = /^NonNullable\s*<(.+)>$/.exec(t);
    if (nonNullableMatch) return this.map(nonNullableMatch[1]!);
    // `Exclude<T, U>` over string-literal unions (the verdict-narrowing idiom — e.g.
    // ByopReviewConsole's `verdict: Exclude<ProofVerificationState, 'PENDING'>`): every
    // member of BOTH operands must resolve (through alias chasing) to a string/numeric
    // literal — the union's compiled carrier is str (or int64) REGARDLESS of the member
    // subtraction, so the mapping IS the first argument's own union mapping. A member
    // that resolves to a struct/other shape keeps the loud fail (the flattened union
    // shape would differ — no fabrication).
    const excludeMatch = /^Exclude\s*<([\s\S]+),\s*([\s\S]+)>$/.exec(t);
    if (excludeMatch && !excludeMatch[1]!.includes("<") && !excludeMatch[2]!.includes("<")) {
      const resolveMembers = (text: string): string[] | undefined => {
        const decl = this.index.typeDeclByName.get(text.trim());
        const target = String((decl as { aliasTarget?: string } | undefined)?.aliasTarget ?? "").length > 0
          ? String((decl as { aliasTarget?: string }).aliasTarget)
          : text.trim();
        const members = splitTopLevelUnion(target).map((m) => stripImportPrefixes(m).trim()).filter((m) => m.length > 0);
        if (members.length === 0) return undefined;
        for (const m of members) {
          if (!/^['"][^'"]*['"]$/.test(m) && !/^(?:string|number)$/.test(m) && this.index.typeDeclByName.get(m) === undefined) {
            // An identifier member is chaseable only when its decl is itself a literal
            // union alias; anything else is outside the literal-union shape.
            const mDecl = this.index.typeDeclByName.get(m);
            const mTarget = String((mDecl as { aliasTarget?: string } | undefined)?.aliasTarget ?? "");
            if (mTarget.length === 0 || !splitTopLevelUnion(mTarget).every((x) => /^['"][^'"]*['"]$/.test(x.trim()))) return undefined;
          }
        }
        return members;
      };
      const tMembers = resolveMembers(excludeMatch[1]!);
      const uMembers = resolveMembers(excludeMatch[2]!);
      if (tMembers !== undefined && uMembers !== undefined) return this.map(excludeMatch[1]!);
    }
    // `ReturnType<typeof X>`: resolve through the named function's own declared return type
    // (exact identity — e.g. `ReturnType<typeof createRealtimeCallSignalEnvelope>` =
    // RealtimeCallSignalEnvelope). Unknown function or unmapped return type falls through to a
    // reason (no fabrication).
    const returnTypeMatch = /^ReturnType\s*<\s*typeof\s+([A-Za-z_$][\w$]*)\s*>$/.exec(t);
    if (returnTypeMatch) {
      const fn = this.index.functionByName.get(returnTypeMatch[1]!);
      if (!fn) return { reason: `ReturnType<typeof ${returnTypeMatch[1]}>: function not found` };
      return this.map(String(fn.returnType ?? ""));
    }
    // Indexed access `T['field']` (e.g. `RealtimeChessSignalEnvelope['action']`): exact
    // field-type lookup through the type_decl member table, recursively mapped — the SAME
    // identity a property_read on a value of T would get. A non-decl base, a missing field, or
    // a field type that itself fails to map all fall through to a reason (no fabrication).
    const indexedMatch = /^([A-Za-z_$][\w$]*)\s*\[\s*'([^']+)'\s*\]$/.exec(t);
    if (indexedMatch) {
      const decl = this.index.typeDeclByName.get(indexedMatch[1]!);
      if (!decl) return { reason: `indexed access base '${indexedMatch[1]}' is not a known type decl` };
      const member = ((decl.members as TypeDeclMember[] | undefined) ?? []).find((m) => m.name === indexedMatch[2]);
      if (!member) return { reason: `indexed access field '${indexedMatch[2]}' not a member of '${indexedMatch[1]}'` };
      return this.map(member.type);
    }
    // `typeof CONST` / `typeof CONST[number]` — resolve through the const-literal type
    // table (string const → str, string-array const indexed by [number] → str). Honest:
    // unknown consts / non-array index fall through to a reason (no fabrication).
    const typeofMatch = /^typeof\s+([A-Za-z_$][\w$]*)\s*(\[\s*(?:number|\d+)\s*\])?$/.exec(t);
    if (typeofMatch) {
      const ct = this.index.constLiteralTypes.get(typeofMatch[1]!);
      if (ct === undefined) {
        const arrElem = this.index.constArrayElemTypes.get(typeofMatch[1]!);
        if (arrElem === undefined) return { reason: `typeof of unknown const '${typeofMatch[1]}'` };
        return this.map(arrElem);
      }
      if (typeofMatch[2]) return ct.endsWith("[]") ? { type: ct.slice(0, -2) } : { reason: `typeof ${typeofMatch[1]}[number] on non-array` };
      return { type: ct };
    }
    const isecParts = splitTopLevelIntersection(t);
    if (isecParts.length > 1) {
      // Intersection A & B (& C ...): member-level confluence. Each side must resolve to a
      // struct-shaped type (a type_decl, an inline object, or an alias of either); members
      // merge by union, with a SAME-Cheng-type field collapse for name collisions (TS
      // intersection of compatible types — e.g. RealtimeBaseEnvelope's kind:'dm'|... (maps to
      // str) & { kind: K } with K instantiated as str collapses to str). A collision between
      // DIFFERENT Cheng types is a real narrowing problem, not silently resolved -> fail loud.
      const merged: TypeDeclMember[] = [];
      const seenFields = new Map<string, string>();
      let failed: string | undefined;
      const collect = (partText: string) => {
        if (failed !== undefined) return;
        const mapped = this.map(partText);
        if (mapped.type === undefined) { failed = `intersection side '${partText}': ${mapped.reason}`; return; }
        const decl = this.index.typeDeclByName.get(mapped.type);
        if (!decl) { failed = `intersection side '${partText}' is not a struct type (${mapped.type})`; return; }
        for (const m of ((decl.members as TypeDeclMember[] | undefined) ?? [])) {
          // m.type is TS text on source decls ("string", "A | B") but already a CHENG type name
          // on synthesized decls ("str" — inline-object members are stored post-mapping), so a
          // failed map() falls back to the raw text (same raw text on both sides conflates
          // cleanly; different raw text rejects — never silently coerced).
          const memberType = this.map(m.type).type ?? m.type;
          const prior = seenFields.get(m.name);
          if (prior !== undefined) {
            if (prior !== (memberType ?? "")) { failed = `intersection member conflict '${m.name}': '${prior}' vs '${memberType ?? "?"}` ; return; }
            continue;
          }
          seenFields.set(m.name, memberType ?? "");
          merged.push(m);
        }
      };
      for (const part of isecParts) collect(part);
      if (failed !== undefined) return { reason: failed };
      const name = `ChtIntersection_${stableInlineTypeHash(t.replace(/\s+/g, " ").trim())}`;
      if (!this.index.typeDeclByName.has(name)) {
        this.index.typeDeclByName.set(name, { kind: "synthesized.intersection", name, members: merged } as CsgFact);
      }
      this.usedStructs.add(name);
      return { type: name };
    }
    const parts = splitTopLevelUnion(t);
    if (parts.length > 1) {
      const nonNull = parts.filter((p) => p !== "null" && p !== "undefined");
      if (nonNull.length === 0) return { reason: "union of only null/undefined" };
      if (nonNull.every((p) => /^['"].*['"]$/.test(p))) return { type: "str" };
      if (nonNull.every((p) => /^-?\d+$/.test(p))) return { type: "int64" };
      if (nonNull.length === 1) {
        const inner = this.map(nonNull[0]!);
        if (inner.type === undefined) return { reason: `nullable inner: ${inner.reason}` };
        if (inner.type === "int64" || inner.type === "str" || inner.type === "bool") return { type: inner.type };
        // `void | undefined` (expression-bodied arrow handlers whose single expression is a
        // void call, e.g. `() => onNavigate?.('trading')`): undefined contributes nothing, so
        // the union IS void — the same identity map("void") already returns for bare `void`.
        if (inner.type === "void") return { type: inner.type };
        // nullable arrays use the empty array as the falsy sentinel: the
        // ubiquitous `x?.length` / `x ?? []` patterns are semantics-equal
        if (inner.type.endsWith("[]")) return { type: inner.type };
        // nullable Record: the zero JsonNode IS the null node
        if (inner.type === "json.JsonNode") return { type: inner.type };
        if (this.index.typeDeclByName.has(inner.type)) return { type: inner.type };
        return { reason: `nullable non-primitive '${nonNull[0]}' not yet supported` };
      }
      if (nonNull.every((p) => /^['"].*['"]$/.test(p) || p === "string")) return { type: "str" };
      // `keyof T` as the checker EXPANDS it (`string | number | symbol` — TS's PropertyKey):
      // the value model's key/text carrier is str, and this subset only ever consumes
      // PropertyKey-typed values as translation/label text keys (PublishDefinition.labelKey
      // family). A member outside the PropertyKey set keeps the general union rules below.
      if (nonNull.every((p) => p === "string" || p === "number" || p === "symbol")) return { type: "str" };
      // Union whose members each independently resolve to str (named string-alias types
      // and `typeof STRING_CONST`, e.g. `PublishType | typeof HOME_APP_CHANNEL`). Pure
      // recursion through the real mapper — no fabrication; mixed/non-str unions still fail.
      if (nonNull.every((p) => this.map(p).type === "str")) return { type: "str" };
      // Union of struct-shaped members (discriminated object-literal unions like
      // MorePanelEntry = { kind: 'action'; ... } | { kind: 'app'; ... } | ...): Cheng has
      // no union representation, but every member is a struct with mappable SCALAR fields,
      // so the union lowers to ONE synthesized struct whose field set is the UNION of the
      // members' fields. A field present in only some members is optional (the same
      // documented optional-absent zero read the Omit acceptance and annotated-literal
      // synthesis already use); a name collision with a DIFFERENT mapped Cheng type is a
      // real narrowing problem -> fail loud (the intersection merge's exact rule).
      const flattened = this.tryFlattenStructUnion(t, nonNull);
      if (flattened !== undefined) return flattened;
      return { reason: `union '${t}' not supported` };
    }
    // Checker-stamped GENERIC INSTANTIATION over a declared decl (`AstrologyRecord<unknown>[]`
    // element spelling): the flat decl table's member list IS the checker's
    // post-instantiation monomorphic layout (the extractor records concrete members; TS
    // generics are erased), so the `<...>` suffix is erasure noise over a DECLARED base and
    // the base name IS the type. Placed after every special-cased generic (Set/Map/Record/
    // Promise/Exclude/...) so only spellings unknown to those strip; a base that is not a
    // declared decl keeps the honest unsupported-type fail. (repro listAstrologyRecords ->
    // ZiweiPage refreshArchives.)
    {
      const genericInst = /^([A-Za-z_$][\w$]*)<[^<>]*(?:<[^<>]*>[^<>]*)*>$/.exec(t);
      if (genericInst && !t.includes(".") && this.index.typeDeclByName.has(genericInst[1]!)) {
        return this.map(genericInst[1]!);
      }
    }
    if (this.index.typeDeclByName.has(t)) {
      const decl = this.index.typeDeclByName.get(t)!;
      const aliasTarget = String(decl.aliasTarget ?? "");
      const members = (decl.members as TypeDeclMember[] | undefined) ?? [];
      // Index-signature record carrier (r2c): a named decl whose member table is EXACTLY one
      // string-keyed index signature (`[key: string]: T`, recorded by the extractor as a
      // member named "[key: string]") has no fixed field set — the value model's carrier for
      // such a record IS json.JsonNode (the same identity `Record<string, V>` already folds
      // to), so every property read composes through json.JsonGetField with the declared
      // value type T. A decl mixing named members with an index signature keeps the struct
      // identity (its named fields are exact reads); a non-member read on it is resolved at
      // the OP layer through the checker's own stamp (indexSignatureCarrierReadType — the
      // stamp carries the signature's json-domain value type) and reads the absent-key json
      // zero. The MAPPER still keeps the struct identity — only the op-layer dispatch
      // changed; an unstamped/inexact read keeps failing loudly — never a fabricated slot.
      // Keyed-namespace budget (the same COLD_MAX_OBJECT_FIELDS contract emitStructs
      // documents): a decl with ≥1024 members is a KEYED NAMESPACE interface (i18n
      // Translations) — it can never materialize as a cheng struct (the cold parser's
      // layout budget), so the model's carrier IS the json dict node (the same identity
      // the string-keyed index-signature record below folds to). Member reads compose
      // through json.JsonGetField (the shell owns the real locale data; an absent node
      // reads the json zero). Never a fabricated layout (repro LiveStreamPage
      // getPublishLocationErrorMessage `t: Translations`, translations.ts 1101 members).
      if (members.length >= 1024) {
        return { type: "json.JsonNode" };
      }
      if (members.length === 1 && /^\[\s*key\s*:\s*string\s*\]$/.test(String(members[0]!.name ?? "").trim())) {
        return { type: "json.JsonNode" };
      }
      if (members.length === 0 && aliasTarget.length > 0) {
        // Recursive JSON-domain alias identity (JsonValue = string | number | boolean |
        // null | JsonValue[] | { [key: string]: JsonValue }): when EVERY union member is a
        // JSON-domain shape — scalars, string literals, self-references (the recursion
        // fixpoint IS the alias), self-arrays, or an index-signature object of the same
        // domain — the alias IS the JSON value domain and json.JsonNode is its exact
        // carrier (the same identity `Record<string, V>` and `[key: string]` decls fold
        // to). A member outside the domain keeps the plain alias-target recursion.
        if (aliasTarget.includes("|") && aliasTarget.includes(t) && this.isRecursiveJsonAliasDomain(t, aliasTarget, 0)) {
          return { type: "json.JsonNode" };
        }
        return this.map(aliasTarget);
      }
      if (members.length === 0) return { reason: `type decl '${t}' has no members` };
      this.usedStructs.add(t);
      return { type: t };
    }
    return { reason: `unsupported type '${t}'` };
  }

  // The JSON-domain membership test for a recursive alias union (see the alias branch
  // above): every member is a scalar/string-literal, the alias itself (the recursion
  // fixpoint), an array of the alias, or an inline index-signature object whose value
  // type is itself in the domain. Depth-bounded — the shape is small and fixed.
  private isRecursiveJsonAliasDomain(aliasName: string, target: string, depth: number): boolean {
    if (depth > 4) return false;
    const inDomain = (part: string, d: number): boolean => {
      const p = stripImportPrefixes(part).trim();
      if (p === aliasName) return true;
      if (p === "string" || p === "number" || p === "boolean" || p === "null" || p === "undefined" || p === "true" || p === "false") return true;
      if (/^['"].*['"]$/.test(p) || /^-?\d+$/.test(p)) return true;
      if (p === `${aliasName}[]`) return true;
      const arrM = /^Array\s*<\s*(.+)\s*>$/.exec(p);
      if (arrM !== null) return inDomain(arrM[1]!, d + 1);
      const objMembers = parseInlineObjectTypeMembers(p);
      if (objMembers !== undefined && objMembers.length === 1 && /^\[\s*key\s*:\s*string\s*\]$/.test(String(objMembers[0]!.name ?? "").trim())) {
        return inDomain(String(objMembers[0]!.type ?? ""), d + 1);
      }
      return false;
    };
    for (const part of splitTopLevelUnion(target)) {
      if (!inDomain(part, depth)) return false;
    }
    return true;
  }

  zeroValueOf(chengType: string): string {
    if (chengType === "int64") return "int64(0)";
    if (chengType === "str") return "\"\"";
    if (chengType === "bool") return "false";
    if (chengType === "json.JsonNode") return "json.NewJObject()";
    if (chengType.endsWith("[]")) return "[]";
    return "";
  }

  emitStructs(): { code: string; diagnostics: string[] } {
    const emitted = new Set<string>();
    // Decl-name -> field lines and struct-reference edges, collected during the work loop and
    // then emitted in TOPOLOGICAL order (dependencies before referencers). The cold compiler
    // computes each object's physical field sizes at parse time from the symbol table as it
    // stands, so a struct textually PRECEDING a struct it references captures a stale layout
    // (repro: AstrologyDailyGuideCard — the props protocol maps the container inline object
    // ChtInlineObj_ebcc64be before the body ever maps AstrologyDailyGuide, so the container
    // entered usedStructs first and its `guide: AstrologyDailyGuide` field stored size 440
    // while the final decl recomputes to 520 -> "Object field ABI drift", then the component
    // fn's sealed TypeId formal died as "sealed function formal TypeId cannot be refined").
    const bodiesByName = new Map<string, string[]>();
    const depsByName = new Map<string, string[]>();
    const diagnostics: string[] = [];
    const queue = [...this.usedStructs];
    while (queue.length > 0) {
      const name = queue.shift()!;
      if (emitted.has(name)) continue;
      emitted.add(name);
      const decl = this.index.typeDeclByName.get(name);
      if (!decl) {
        diagnostics.push(`struct '${name}' has no type decl`);
        continue;
      }
      // Inheritance expansion at EMISSION time (CHT_INTERFACE_SUPERS): the extractor records
      // only an interface's OWN members, but a Cheng struct's PHYSICAL layout must carry the
      // inherited fields too (TS interface extends is full-field — the RealtimeBaseEnvelope
      // fields (messageId/timestampMs/...) physically exist on every RealtimeEnvelope member,
      // and their JSON serializations require them). Parent members come FIRST (base layout
      // prefix), own members override on name conflict (same rule as TS extends).
      const ownMembers = (decl.members as TypeDeclMember[] | undefined) ?? [];
      const superChain: string[] = [];
      {
        let cur = CHT_INTERFACE_SUPERS.get(name);
        const seenSupers = new Set<string>();
        while (cur !== undefined && !seenSupers.has(cur)) {
          seenSupers.add(cur);
          superChain.unshift(cur);
          cur = CHT_INTERFACE_SUPERS.get(cur);
        }
      }
      const memberMap = new Map<string, TypeDeclMember>();
      for (const sup of superChain) {
        const supDecl = this.index.typeDeclByName.get(sup);
        for (const m of ((supDecl?.members as TypeDeclMember[] | undefined) ?? [])) if (!memberMap.has(m.name)) memberMap.set(m.name, m);
      }
      for (const m of ownMembers) memberMap.set(m.name, m);
      const members = [...memberMap.values()];
      // Cold object-layout budget (COLD_MAX_OBJECT_FIELDS = 1024 in bootstrap
      // cold_parser.c): a struct with ≥1024 members can never parse. Keyed namespace
      // interfaces (i18n Translations) reach usedStructs through type queries but no body
      // ever declares a value of them (the reads go through their bridge channel), so the
      // honest emission is a named skip, never a guaranteed cold die.
      if (members.length >= 1024) {
        diagnostics.push(`struct '${name}': ${members.length} fields exceed the cold object layout budget (keyed namespace interface — consumed through its bridge channel; not emitted)`);
        continue;
      }
      const fieldLines: string[] = [`    ${name} =`];
      const deps: string[] = [];
      for (const member of members) {
        const before = new Set(this.usedStructs);
        const mapped = this.map(member.type);
        if (mapped.type === undefined) {
          diagnostics.push(`struct '${name}.${member.name}': ${mapped.reason}`);
          continue;
        }
        for (const used of this.usedStructs) if (!before.has(used)) queue.push(used);
        // Struct-reference edge: the field's mapped type (array wrappers stripped — the
        // element decl is part of the physical layout too) that names a decl in this
        // emission batch must be emitted BEFORE this struct.
        const depBase = mapped.type.replace(/(\[\])+$/, "");
        if (depBase !== name && this.index.typeDeclByName.has(depBase)) deps.push(depBase);
        fieldLines.push(`        ${sanitizeFieldName(member.name)}: ${mapped.type}`);
      }
      if (fieldLines.length > 1) {
        bodiesByName.set(name, fieldLines);
        depsByName.set(name, deps);
      }
    }
    // Topological emission: DFS post-order over the collected edges, roots in insertion
    // order (deterministic — same usedStructs order, same output). A reference cycle would
    // be a by-value struct containing itself (no finite layout exists in any order); it is
    // reported loudly and its members fall back to insertion order rather than looping.
    const ordered: string[][] = [];
    const done = new Set<string>();
    const inProgress = new Set<string>();
    const visit = (name: string): void => {
      if (done.has(name)) return;
      if (inProgress.has(name)) {
        diagnostics.push(`struct '${name}' participates in a by-value reference cycle — no finite layout`);
        return;
      }
      inProgress.add(name);
      for (const dep of depsByName.get(name) ?? []) if (bodiesByName.has(dep)) visit(dep);
      inProgress.delete(name);
      done.add(name);
      const body = bodiesByName.get(name);
      if (body !== undefined) ordered.push(body);
    };
    for (const name of bodiesByName.keys()) visit(name);
    if (ordered.length === 0) return { code: "", diagnostics };
    const lines = ["type"];
    for (const body of ordered) lines.push(...body);
    return { code: lines.join("\n"), diagnostics };
  }
}

export function stripImportPrefixes(t: string): string {
  // `import("...").Name` — the plain import-qualified type text. The second alternative
  // also strips the import-ATTRIBUTES form the checker stamps on dual-mode resolutions
  // (`import("$root/app/publish/metadata", { with: { "resolution-mode": "import" } })
  // .PublishDefinition` — PublishTypeSelector's re-exported publishTypes element type);
  // both spellings denote the same named type in the project namespace.
  return t
    .replace(/import\("[^"]*",\s*\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}\s*\)\./g, "")
    .replace(/import\("[^"]*"\)\./g, "");
}

function balancedParens(t: string): boolean {
  let depth = 0;
  for (let i = 0; i < t.length; i++) {
    if (t[i] === "(") depth++;
    else if (t[i] === ")") {
      depth--;
      if (depth === 0 && i < t.length - 1) return false;
    }
  }
  return depth === 0;
}

function splitTopLevelUnion(t: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let current = "";
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]!;
    if (ch === "<" || ch === "(" || ch === "[" || ch === "{") depth++;
    else if (ch === ">" || ch === ")" || ch === "]" || ch === "}") depth--;
    if (ch === "|" && depth === 0) {
      parts.push(current.trim());
      current = "";
      continue;
    }
    current += ch;
  }
  parts.push(current.trim());
  return parts.filter((p) => p.length > 0);
}

function splitTopLevelIntersection(t: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let quote = "";
  let current = "";
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]!;
    if (quote.length > 0) {
      current += ch;
      if (ch === "\\") { current += t[i + 1] ?? ""; i++; }
      else if (ch === quote) quote = "";
      continue;
    }
    if (ch === "'" || ch === '"' || ch === "`") { quote = ch; current += ch; continue; }
    if (ch === "<" || ch === "(" || ch === "[" || ch === "{") depth++;
    else if (ch === ">" || ch === ")" || ch === "]" || ch === "}") depth--;
    if (ch === "&" && depth === 0) {
      parts.push(current.trim());
      current = "";
      continue;
    }
    current += ch;
  }
  parts.push(current.trim());
  return parts.filter((p) => p.length > 0);
}

function splitTopLevelObjectMembers(t: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let quote = "";
  let current = "";
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]!;
    if (quote.length > 0) {
      current += ch;
      if (ch === "\\" && i + 1 < t.length) {
        i += 1;
        current += t[i]!;
      } else if (ch === quote) {
        quote = "";
      }
      continue;
    }
    if (ch === "\"" || ch === "'") {
      quote = ch;
      current += ch;
      continue;
    }
    if (ch === "<" || ch === "(" || ch === "[" || ch === "{") depth++;
    else if (ch === ">" || ch === ")" || ch === "]" || ch === "}") depth--;
    if ((ch === ";" || ch === ",") && depth === 0) {
      const item = current.trim();
      if (item.length > 0) parts.push(item);
      current = "";
      continue;
    }
    current += ch;
  }
  const tail = current.trim();
  if (tail.length > 0) parts.push(tail);
  return parts;
}

// `[A, B, ...]` head extraction helper: the text before the FIRST depth-0 comma
// (quote/bracket aware, same depth rules as splitTopLevelObjectMembers).
function sliceUpToTopLevelComma(t: string): string {
  let depth = 0;
  let quote = "";
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]!;
    if (quote.length > 0) {
      if (ch === "\\" && i + 1 < t.length) i += 1;
      else if (ch === quote) quote = "";
      continue;
    }
    if (ch === "\"" || ch === "'") { quote = ch; continue; }
    if (ch === "<" || ch === "(" || ch === "[" || ch === "{") depth++;
    else if (ch === ">" || ch === ")" || ch === "]" || ch === "}") depth--;
    if (ch === "," && depth === 0) return t.slice(0, i);
  }
  return t;
}

function parseInlineObjectTypeMembers(t: string): TypeDeclMember[] | undefined {
  const text = t.trim();
  if (!text.startsWith("{") || !text.endsWith("}")) return undefined;
  const body = text.slice(1, -1).trim();
  if (body.length === 0) return undefined;
  const members: TypeDeclMember[] = [];
  for (const part of splitTopLevelObjectMembers(body)) {
    // `readonly` member modifier (`{ readonly points: "..." }` — as-const object return
    // types, STORAGE_KEYS family): TS immutability has no value-model representation to
    // begin with (the emitted structs map it away everywhere else), so the parser strips
    // it — the member NAME is what follows. Without this the whole inline-object parse
    // abandons and the type keeps failing as unsupported.
    const match = /^(?:readonly\s+)?([A-Za-z_$][\w$]*|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')(\?)?\s*:\s*([\s\S]+)$/.exec(part);
    if (!match) return undefined;
    const rawName = match[1]!;
    const name = rawName.startsWith("\"") || rawName.startsWith("'") ? rawName.slice(1, -1) : rawName;
    members.push({ name, optional: match[2] === "?", type: match[3]!.trim() });
  }
  return members.length > 0 ? members : undefined;
}

function stableInlineTypeHash(text: string): string {
  let hash = 2166136261 >>> 0;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}

// Module-specifier identity for import()-qualified type resolution: strip the `$root/`
// project prefix and the trailing `.ts`/`.tsx` extension so `import("$root/app/x/y")`
// and decl loc.file `app/x/y.ts` normalize to one key.
function normalizeModuleSpecKey(pathText: string): string {
  return pathText.replace(/^\$root\//, "").replace(/\.tsx?$/, "");
}

// Resolve a RELATIVE import module specifier against the importing file's own
// project-relative path: "./components/HomePage" from "app/App.tsx" ->
// "app/components/HomePage" (the same normalized, extensionless project-relative
// space every decl loc.file normalizes through normalizeModuleSpecKey). Non-relative
// specifiers (bare packages, `#` subspecifiers) and degenerate escapes return
// undefined — the caller keeps the name unresolved rather than guessing an identity.
function resolveModuleSpec(importingFile: string, moduleSpec: string): string | undefined {
  if (!moduleSpec.startsWith(".")) return undefined;
  const baseParts = importingFile.split("/").slice(0, -1);
  for (const part of moduleSpec.split("/")) {
    if (part === "." || part.length === 0) continue;
    if (part === "..") {
      if (baseParts.pop() === undefined) return undefined;
      continue;
    }
    baseParts.push(part.replace(/\.(tsx?|jsx?)$/, ""));
  }
  const resolved = baseParts.join("/");
  return resolved.length > 0 ? resolved : undefined;
}

// Rewrite the bare-identifier type tokens of a type TEXT through a file's named-import
// table (see TranspilerFactIndex.typeImportsByFile): every standalone identifier that
// names one of the file's import bindings becomes that binding's exact module identity
// (`Player[]` -> `import("app/games/werewolf/engine").Player[]`). Identifier positions
// only — never a `.`-property access, a quoted literal-type body, or a `typeof ` operand
// (value namespace). Names absent from the table pass through unchanged.
function rewriteLocalTypeImports(text: string, table: Map<string, string>): string {
  if (table.size === 0) return text;
  return text.replace(/(?<![\w$."'])(?<!typeof\s)([A-Za-z_$][\w$]*)(?![\w$])/g, (full, name: string) => {
    const spec = table.get(name);
    if (spec === undefined) return full;
    return `import("${spec}").${name}`;
  });
}

function inlineObjectTypeName(t: string): string {
  return `ChtInlineObj_${stableInlineTypeHash(stripImportPrefixes(t).replace(/\s+/g, " ").trim())}`;
}

// Order-insensitive member-set identity for the structural-twin lookup: names carry the
// match (TS object members are a name-keyed set), each entry pins optionality and the
// whitespace-normalized type text.
function structMemberSignature(members: TypeDeclMember[]): string {
  return members
    .map((m) => `${m.name}=${m.optional === true ? 1 : 0}:${String(m.type).replace(/\s+/g, " ").trim()}`)
    .sort()
    .join("|");
}

const CHENG_KEYWORDS = new Set([
  "type", "fn", "var", "let", "const", "if", "elif", "else", "while", "for",
  "in", "return", "import", "true", "false", "nil", "and", "or", "not",
  "break", "continue", "pass", "struct", "enum", "match", "defer",
]);

function sanitizeFieldName(name: string): string {
  if (CHENG_KEYWORDS.has(name)) return `f_${name}`;
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(name) ? name : `f_${name.replace(/[^A-Za-z0-9_]/g, "_")}`;
}

