        const cFv = cCbArgs.length >= 1 ? this.index.opsById.get(String(cCbArgs[0])) : undefined;
        if (cFv === undefined || cFv.opKind !== "function_value") return undefined;
        const cArrow = this.resolveArrowReturnExpr(String(cCbArgs[0]));
