  const propsZeroVarsCode = propsZeroVarLines.length > 0 ? propsZeroVarLines.join("\n") : "";
  const r2cPreludeParts = [slotResult.code, refResult.code];
  r2cPreludeParts.push(...hookSlotCodes);
  r2cPreludeParts.push(...hookDerivedFnCodes);
  if (capturedHoistSlotsText.length > 0) r2cPreludeParts.push(capturedHoistSlotsText);
